"""``POST /auth/login`` and ``GET /auth/whoami`` (FR-2)."""

from __future__ import annotations

from fastapi import APIRouter, Depends, HTTPException, status
from pydantic import BaseModel
from sqlmodel import Session

from api.deps import get_current_user
from models.database import get_session
from models.enums import Role
from models.user import User
from services.auth import InvalidCredentialsError, login

router = APIRouter(prefix="/auth", tags=["auth"])


class LoginRequest(BaseModel):
    email: str
    password: str


class UserOut(BaseModel):
    id: int
    org_id: int
    email: str
    name: str
    role: Role


class LoginResponse(BaseModel):
    token: str
    user: UserOut


@router.post("/login", response_model=LoginResponse)
def login_route(payload: LoginRequest, session: Session = Depends(get_session)) -> LoginResponse:
    try:
        user, token = login(session, payload.email, payload.password)
    except InvalidCredentialsError as exc:
        # Deliberately generic: never reveal whether the email or the
        # password was wrong (FR-2).
        raise HTTPException(
            status_code=status.HTTP_401_UNAUTHORIZED,
            detail="Email or password is incorrect",
        ) from exc
    return LoginResponse(token=token, user=UserOut.model_validate(user, from_attributes=True))


@router.get("/whoami", response_model=UserOut)
def whoami_route(user: User = Depends(get_current_user)) -> UserOut:
    return UserOut.model_validate(user, from_attributes=True)

"""``missionctl`` — a thin HTTP client over the Mission Control API.

Talks to the API over ``httpx`` only; never touches the database or the
``services``/``models`` layers directly (FR-18). Output is JSON,
pretty-printed (§10 #15).

The session (bearer token + basic profile) issued by ``login`` is cached
locally at ``~/.missionctl/session.json`` (override via
``MISSIONCTL_SESSION_FILE``, mainly for tests) so later commands don't need
the token pasted in every time. The file is written best-effort
owner-only (``chmod 600``) since it holds a live bearer token.
"""

from __future__ import annotations

import contextlib
import json
import os
from pathlib import Path
from typing import Any

import httpx
import typer

app = typer.Typer(
    name="missionctl",
    help="A thin HTTP client over the Mission Control API.",
)

DEFAULT_API_BASE_URL = "http://127.0.0.1:8000"


def _api_base_url() -> str:
    return os.environ.get("MISSIONCTL_API_BASE_URL", DEFAULT_API_BASE_URL)


def _session_file() -> Path:
    override = os.environ.get("MISSIONCTL_SESSION_FILE")
    if override:
        return Path(override)
    return Path.home() / ".missionctl" / "session.json"


def _save_session(token: str, user: dict[str, Any]) -> None:
    path = _session_file()
    path.parent.mkdir(parents=True, exist_ok=True)
    path.write_text(json.dumps({"token": token, "user": user}, indent=2))
    # Best-effort only — e.g. unsupported on some Windows filesystems.
    with contextlib.suppress(OSError):
        os.chmod(path, 0o600)


def _load_session() -> dict[str, Any] | None:
    path = _session_file()
    if not path.exists():
        return None
    return json.loads(path.read_text())


def _print_json(payload: Any) -> None:
    typer.echo(json.dumps(payload, indent=2))


def _error_detail(response: httpx.Response) -> Any:
    if not response.content:
        return response.reason_phrase
    try:
        return response.json().get("detail", response.text)
    except ValueError:
        return response.text


@app.command()
def version() -> None:
    """Print the CLI version."""
    typer.echo("missionctl 0.1.0")


@app.command()
def login(email: str, password: str) -> None:
    """Log in and cache the issued bearer token locally."""
    response = httpx.post(
        f"{_api_base_url()}/auth/login",
        json={"email": email, "password": password},
    )
    if response.status_code != httpx.codes.OK:
        _print_json({"error": _error_detail(response)})
        raise typer.Exit(code=1)

    data = response.json()
    _save_session(data["token"], data["user"])
    _print_json({"status": "logged in", "user": data["user"]})


@app.command()
def whoami() -> None:
    """Show the currently logged-in user, verified against the API."""
    session_data = _load_session()
    if session_data is None:
        _print_json({"error": "Not logged in. Run `missionctl login <email> <password>`."})
        raise typer.Exit(code=1)

    response = httpx.get(
        f"{_api_base_url()}/auth/whoami",
        headers={"Authorization": f"Bearer {session_data['token']}"},
    )
    if response.status_code != httpx.codes.OK:
        _print_json({"error": "Session invalid or expired. Run `missionctl login` again."})
        raise typer.Exit(code=1)

    _print_json(response.json())


if __name__ == "__main__":
    app()

"""Auth + RBAC + tenant scoping (T2, FR-1/FR-2/FR-3).

Representative cases per §10 #17 / the T2 acceptance checklist, not
exhaustive coverage: login success/failure, missing/invalid token on a
protected route, role-mismatch 403, and cross-org 404.
"""

from __future__ import annotations

import hashlib

from fastapi.testclient import TestClient
from sqlmodel import Session, select

from models.auth_token import AuthToken
from tests.conftest import SeededUser


def test_login_success_issues_a_bearer_token(
    client: TestClient, seed_users: dict[str, SeededUser]
) -> None:
    director = seed_users["director_a"]

    response = client.post(
        "/auth/login", json={"email": director.email, "password": director.password}
    )

    assert response.status_code == 200
    body = response.json()
    assert body["user"]["email"] == director.email
    assert body["user"]["role"] == "director"
    assert body["user"]["org_id"] == director.org_id
    assert isinstance(body["token"], str) and len(body["token"]) > 20


def test_login_stores_only_the_hashed_token(
    client: TestClient, session: Session, seed_users: dict[str, SeededUser]
) -> None:
    director = seed_users["director_a"]

    response = client.post(
        "/auth/login", json={"email": director.email, "password": director.password}
    )
    raw_token = response.json()["token"]

    expected_hash = hashlib.sha256(raw_token.encode("utf-8")).hexdigest()
    stored = session.exec(select(AuthToken)).all()
    assert any(row.token_hash == expected_hash for row in stored)
    # The raw token itself never appears as a stored hash.
    assert all(row.token_hash != raw_token for row in stored)


def test_login_wrong_password_is_401_with_generic_message(
    client: TestClient, seed_users: dict[str, SeededUser]
) -> None:
    director = seed_users["director_a"]

    response = client.post(
        "/auth/login", json={"email": director.email, "password": "not-the-password"}
    )

    assert response.status_code == 401
    detail = response.json()["detail"].lower()
    assert "email or password is incorrect" in detail
    # Never reveals which one was wrong.
    assert "password" not in detail.replace("email or password is incorrect", "")


def test_login_unknown_email_is_401_with_same_generic_message(client: TestClient) -> None:
    response = client.post(
        "/auth/login", json={"email": "nobody@example.com", "password": "whatever"}
    )

    assert response.status_code == 401
    assert response.json()["detail"].lower() == "email or password is incorrect"


def test_protected_route_without_a_token_is_401(client: TestClient) -> None:
    response = client.get("/auth/whoami")

    assert response.status_code == 401


def test_protected_route_with_an_invalid_token_is_401(client: TestClient) -> None:
    response = client.get("/auth/whoami", headers={"Authorization": "Bearer not-a-real-token"})

    assert response.status_code == 401


def test_whoami_with_a_valid_token_returns_the_caller(
    client: TestClient, seed_users: dict[str, SeededUser]
) -> None:
    crew = seed_users["crew_a"]
    login_response = client.post(
        "/auth/login", json={"email": crew.email, "password": crew.password}
    )
    token = login_response.json()["token"]

    response = client.get("/auth/whoami", headers={"Authorization": f"Bearer {token}"})

    assert response.status_code == 200
    assert response.json()["email"] == crew.email


def test_disallowed_role_gets_403_naming_the_required_role(
    client: TestClient, seed_users: dict[str, SeededUser]
) -> None:
    lead = seed_users["lead_a"]
    login_response = client.post(
        "/auth/login", json={"email": lead.email, "password": lead.password}
    )
    token = login_response.json()["token"]

    response = client.get(
        f"/users/{seed_users['crew_a'].id}",
        headers={"Authorization": f"Bearer {token}"},
    )

    assert response.status_code == 403
    assert "director" in response.json()["detail"].lower()


def test_cross_org_record_is_404_not_403(
    client: TestClient, seed_users: dict[str, SeededUser]
) -> None:
    director_a = seed_users["director_a"]
    director_b = seed_users["director_b"]
    login_response = client.post(
        "/auth/login", json={"email": director_a.email, "password": director_a.password}
    )
    token = login_response.json()["token"]

    response = client.get(
        f"/users/{director_b.id}",
        headers={"Authorization": f"Bearer {token}"},
    )

    assert response.status_code == 404


def test_same_org_record_is_visible_to_an_allowed_role(
    client: TestClient, seed_users: dict[str, SeededUser]
) -> None:
    director_a = seed_users["director_a"]
    crew_a = seed_users["crew_a"]
    login_response = client.post(
        "/auth/login", json={"email": director_a.email, "password": director_a.password}
    )
    token = login_response.json()["token"]

    response = client.get(
        f"/users/{crew_a.id}",
        headers={"Authorization": f"Bearer {token}"},
    )

    assert response.status_code == 200
    assert response.json()["email"] == crew_a.email

